// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Written from the approved requirement-to-plan matrix (traceability_matrix.md),
// not from the RTL. Sampling: every rising edge of clk, using the port values
// just before the edge (count/empty/full are the stack as it stood before it).
//
// CLOSURE STATEMENT
// Planned bins (15):
//   Crosses (rst_n high). Op: push alone = push & !pop, pop alone = !push & pop,
//   both = push & pop. Occupancy: empty = count 0, mid = count 1..3, full = count 4.
//   bin  0  push alone, empty    LIFO-PUSH
//   bin  1  push alone, mid      LIFO-PUSH
//   bin  2  push alone, full     LIFO-OVERFLOW
//   bin  3  pop alone,  empty    LIFO-UNDERFLOW
//   bin  4  pop alone,  mid      LIFO-POP
//   bin  5  pop alone,  full     LIFO-POP
//   bin  6  both,       empty    LIFO-BOTH-EMPTY
//   bin  7  both,       mid      LIFO-REPLACE
//   bin  8  both,       full     LIFO-REPLACE
//   Occupancy levels (rst_n high), all requirements:
//   bin  9  count == 0
//   bin 10  count == 1
//   bin 11  count == 2
//   bin 12  count == 3
//   bin 13  count == 4
//   Reset:
//   bin 14  rst_n low at an edge while the stack holds a word (count 1..4)  LIFO-RESET
// Exclusions: none. The matrix names no unreachable scenario and waives none.
// Bins are sampled only after the first observed reset, so that undefined
// power-up state cannot hit a bin.
// planned = 15 (bins tracked); holes = planned bins not yet hit.

module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);

    localparam int NBINS = 15;

    logic [NBINS-1:0] hit = '0;
    logic             seen_reset = 1'b0;

    logic op_push, op_pop, op_both;
    logic occ_empty, occ_mid, occ_full;

    assign op_push   =  push && !pop;
    assign op_pop    = !push &&  pop;
    assign op_both   =  push &&  pop;
    assign occ_empty = (count == 3'd0);
    assign occ_mid   = (count >= 3'd1) && (count <= 3'd3);
    assign occ_full  = (count == 3'd4);

    always @(posedge clk) begin
        if (!rst_n) begin
            if (seen_reset && (count != 3'd0) && (count <= 3'd4))
                hit[14] <= 1'b1;
            seen_reset <= 1'b1;
        end else if (seen_reset) begin
            if (op_push && occ_empty) hit[0] <= 1'b1;
            if (op_push && occ_mid)   hit[1] <= 1'b1;
            if (op_push && occ_full)  hit[2] <= 1'b1;
            if (op_pop  && occ_empty) hit[3] <= 1'b1;
            if (op_pop  && occ_mid)   hit[4] <= 1'b1;
            if (op_pop  && occ_full)  hit[5] <= 1'b1;
            if (op_both && occ_empty) hit[6] <= 1'b1;
            if (op_both && occ_mid)   hit[7] <= 1'b1;
            if (op_both && occ_full)  hit[8] <= 1'b1;
            case (count)
                3'd0: hit[9]  <= 1'b1;
                3'd1: hit[10] <= 1'b1;
                3'd2: hit[11] <= 1'b1;
                3'd3: hit[12] <= 1'b1;
                3'd4: hit[13] <= 1'b1;
                default: $error("lifo4_fcov: illegal count %0d out of reset", count);
            endcase
        end
    end

    assign planned = NBINS;
    assign holes   = NBINS - $countones(hit);

endmodule
=== END FILE ===
